    C c;
    constructor(C _c) { c = _c; }

    // Drive with arbitrary addresses and assert behavior distinguishing approvedToLog implementation.
    // If caller is not approved, logging functions must return false (no-op). The mutant that makes
    // approvedToLog always true would make such calls return true, violating the rule.
    function check_unapproved_logging(address someKeep, address requester, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes32 txid, uint256 utxoSize, bytes calldata outpoint, bytes calldata redeemerOutputScript, uint256 requestedFee) public {
        // ensure this contract (msg.sender) is not approved by owner in original; we cannot call setApprovedLogger
        // because only owner can, and we don't assume this contract is owner. So treat this contract as unapproved caller.
        // Call several logging methods that should return false for unapproved caller.
        bool a = c.logCreated(someKeep);
        bool b = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        bool d = c.logGotRedemptionSignature(digest, r, s);
        bool e = c.logRegisteredPubkey(pubX, pubY);
        bool f = c.logSetupFailed();
        bool g = c.logFraudDuringSetup();
        bool h = c.logFunded();
        bool i = c.logCourtesyCalled();
        bool j = c.logStartedLiquidation(true);
        bool k = c.logRedeemed(txid);
        bool l = c.logLiquidated();
        bool m = c.logExitedCourtesyCall();

        // The distinguishing rule: for an unapproved caller, ALL these log calls must return false.
        // This holds on original contract (approvedToLog checks mapping). Mutant that returns true unconditionally breaks it.
        assert(!a && !b && !d && !e && !f && !g && !h && !i && !j && !k && !l && !m);
    }
}

